// Dimensionless end-stub Laplacians. No material resistance is selected here.
#include "../charge_compiler/json.hpp"
#include "sparse_runs_v2.hpp"
#include <gmpxx.h>
#include <filesystem>
#include <map>
#include <set>
#include <iostream>
using I=long long;
struct Coefficient{mpq_class q;uint64_t terms=0;};
int main(int argc,char**argv){try{
 require(argc==2,"usage: compile_symbolic_end_G CONFIG");auto cfg=Json::read(argv[1]);I nodes=cfg.at("voltage_nodes").integer();require(nodes>1&&nodes<100000000,"bounded symbolic voltage namespace");std::map<std::string,std::map<uint64_t,Coefficient>> matrices;std::map<std::string,I> counts;std::set<I> ends;I total=0;
 for(auto& path:cfg.at("symbolic_parts").arr()){std::ifstream input(path.str());require(bool(input),"symbolic end source");std::string line;while(std::getline(input,line)){auto row=Json::parse(line);require(!row.at("finite_conductance_assigned").boolean(),"unresolved end must have no guessed conductance");auto material=row.at("requires_sheet_model_for_material").str();require(!material.empty()&&material.find_first_not_of("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_")==std::string::npos,"material identifier");I a=row.at("global_voltage_ids").at(0).integer(),b=row.at("global_voltage_ids").at(1).integer();require(a>0&&b>0&&a<nodes&&b<nodes&&a!=b&&ends.insert(a).second,"distinct symbolic end/native anchor");require(row.at("private_endpoints").at(0).str().starts_with("_zero_R_")&&row.at("private_endpoints").at(1).str().starts_with("_rmesh_"),"symbolic end identity roles");auto& square=row.at("resistance_squares_exact");mpq_class r(square.at(0).str()+"/"+square.at(1).str());r.canonicalize();require(r>0,"positive exact geometric resistance squares");mpq_class g=1/r;auto& k=matrices[material];auto add=[&](I i,I j,const mpq_class& q){if(i>j)std::swap(i,j);auto& c=k[(uint64_t(i)<<32)|uint64_t(j)];c.q+=q;c.terms++;};add(a,a,g);add(b,b,g);add(a,b,-g);counts[material]++;total++;}require(input.eof(),"complete symbolic end source");}
 require(total==cfg.at("expected_symbolic_ends").integer(),"complete symbolic end coverage");auto out=std::filesystem::path(cfg.at("output").str());require(std::filesystem::create_directory(out),"fresh symbolic end matrix directory");Json families=Json::array();for(auto&[material,k]:matrices){std::map<uint32_t,mpq_class> sums;std::vector<sparse::Record> records;for(auto&[key,c]:k){auto a=uint32_t(key>>32),b=uint32_t(key);sums[a]+=c.q;if(a!=b)sums[b]+=c.q;require(a==b?c.q>0:c.q<0,"positive symbolic Laplacian edges");long double value=std::stold(c.q.get_num().get_str())/std::stold(c.q.get_den().get_str());records.push_back({key,value,std::fabs(value),c.terms});}for(auto&[node,q]:sums)require(q==0,"exact symbolic constant nullspace");auto file=out/(material+".unit_square_G.bin");sparse::write(file.string(),records);Json row=Json::object();row["material"]=material;row["symbolic_end_stubs"]=counts[material];row["upper_entries"]=I(records.size());row["unit_square_matrix"]=file.string();row["coefficient_multiplier_to_siemens"]="1000 / material_sheet_milliohms_per_square";row["material_sheet_value_selected"]=false;families.push(row);}
 Json report=Json::object();report["symbolic_end_stubs"]=total;report["material_families"]=families;report["exact_geometric_Laplacians_verified"]=true;report["numeric_material_law_selected"]=false;report["physical_RC_qualified"]=false;report["release_qualified"]=false;std::cout<<report.dump()<<'\n';return 0;
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 2;}}
